import { authoring } from "./authoring";

const { toEs, fe, wo, mc } = authoring("es");

// Prompts that fix the target structure when the English cue alone would allow others.
const NODEB = "Traduce al español sin «deber», «suponer» ni adverbios de duda (quizás, probablemente…).";
const FUT = NODEB;
const COND = NODEB;
const PROB = NODEB;
const DIAL = NODEB;
const TENSE = "Traduce al español con el tiempo de conjetura que corresponda al momento (futuro, futuro perfecto, condicional o condicional perfecto).";
const CONC = "Traduce al español sin «aunque», «quizás» ni el verbo «poder».";

// «a lo mejor» takes only the indicative; quizás / quizá / tal vez take either mood.
const MARKERS = ["Quizás", "Quizá", "Tal vez"];
const maybe = (source: string, ind: string[], sub: string[], explanation: string, extra: string[] = [], fut: string[] = [], prompt?: string) => {
  const all = [
    ...sub.flatMap((s) => MARKERS.map((m) => `${m} ${s}`)),
    ...[...ind, ...fut].flatMap((s) => [`A lo mejor ${s}`, ...MARKERS.map((m) => `${m} ${s}`)]),
  ];
  return toEs(source, all[0], explanation, [...all.slice(1), ...extra], prompt);
};

